export function moveItemInArray<ItemType>(
    sourceIndex: number,
    destinationIndex: number,
    array: ItemType[],
): void {
    if (array.length === 0) {
        return;
    }

    const [item] = array.splice(sourceIndex, 1);

    if (item !== undefined) {
        array.splice(destinationIndex, 0, item);
    }
}
